def is_maximal_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check triangle-free
    for u in range(n):
        for v in adj[u]:
            if adj[u].intersection(adj[v]):
                return False, "Contains triangle"

    # Check maximal
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                # If we add (u, v), does it create a triangle?
                # It creates a triangle if u and v share a neighbor
                if not adj[u].intersection(adj[v]):
                    return False, f"Not maximal: can add edge ({u}, {v})"

    return True, "Maximal triangle-free"

edges = []
for i in range(6):
    for j in range(6, 12):
        edges.append((i, j))

print(is_maximal_triangle_free(edges, 12))

